from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class BrgprtParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.set_parameter('ethlkDN', f"MRBTS-{self.enb_ent_config['id']}/TNLSVC-1/TNL-1/ETHSVC-1/ETHLK-1")
        self.set_l2BurstSize(execution_config)
        if execution_config['release'] >= 21.7:
            self.set_parameter('l2ShaperRate', 1000000)

    def set_l2BurstSize(self, execution_config):
        if execution_config['is_fsm4']:
            self.set_parameter('l2BurstSize', 1048576)
        else:
            self.set_parameter('l2BurstSize', 1048500)
